const ZIP_V = (() => { const m = new Int8Array(128).fill(-1);
  for (let i = 0; i < 64; i++) m[ZIP_A.charCodeAt(i)] = i; return m; })();
const zipD3 = (s, i) => (ZIP_V[s.charCodeAt(i)] << 12)
  | (ZIP_V[s.charCodeAt(i + 1)] << 6) | ZIP_V[s.charCodeAt(i + 2)];

