/** [lat, lon] for a five-digit ZIP, or null when it is not a real ZIP. */
function zipCentroid(zip) {
  const z = String(zip == null ? '' : zip).match(/(\d{5})/);
  if (!z) return null;
  const code = z[1];
  const p = +code.slice(0, 3);
  if (!(p >= 0 && p < 1000)) return null;
  const lo = zipD3(ZIP_DIR, p * 3), hi = zipD3(ZIP_DIR, p * 3 + 3);
  const tail = code.slice(3);
  for (let i = lo; i < hi; i++) {
    const o = i * 8;
    if (ZIP_BODY[o] === tail[0] && ZIP_BODY[o + 1] === tail[1]) {
      return [zipD3(ZIP_BODY, o + 2) / 1000 - 90, zipD3(ZIP_BODY, o + 5) / 500 - 180];
    }
  }
  return null;
}

